import{_ as t,o as a,c as s,ag as d}from"./chunks/framework.DEqXEGcv.js";const u=JSON.parse('{"title":"Data Types","description":"","frontmatter":{},"headers":[],"relativePath":"language/data-types.md","filePath":"language/data-types.md"}'),i={name:"language/data-types.md"};function o(n,e,c,l,p,r){return a(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data Types&quot;">​</a></h1><p>SMQL supports 16 data types for instance fields.</p><h2 id="scalar-types" tabindex="-1">Scalar Types <a class="header-anchor" href="#scalar-types" aria-label="Permalink to &quot;Scalar Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>JSON Representation</th><th>Example</th></tr></thead><tbody><tr><td><code>TEXT</code></td><td>Unicode string</td><td><code>&quot;hello&quot;</code></td><td><code>name : TEXT</code></td></tr><tr><td><code>INT</code></td><td>64-bit signed integer</td><td><code>42</code></td><td><code>count : INT</code></td></tr><tr><td><code>FLOAT</code></td><td>64-bit floating point</td><td><code>3.14</code></td><td><code>rating : FLOAT</code></td></tr><tr><td><code>BOOL</code></td><td>Boolean</td><td><code>true</code> / <code>false</code></td><td><code>active : BOOL</code></td></tr><tr><td><code>UUID</code></td><td>UUID v4/v7</td><td><code>&quot;550e8400-...&quot;</code></td><td><code>user_id : UUID</code></td></tr><tr><td><code>DATE</code></td><td>Calendar date</td><td><code>&quot;2026-02-16&quot;</code></td><td><code>due_date : DATE</code></td></tr><tr><td><code>DATETIME</code></td><td>Date with time (UTC)</td><td><code>&quot;2026-02-16T10:00:00Z&quot;</code></td><td><code>created : DATETIME</code></td></tr><tr><td><code>DURATION</code></td><td>Time duration</td><td><code>&quot;7d&quot;</code> / <code>&quot;24h&quot;</code></td><td><code>sla : DURATION</code></td></tr><tr><td><code>JSON</code></td><td>Arbitrary JSON</td><td><code>{...}</code></td><td><code>metadata : JSON</code></td></tr><tr><td><code>BLOB</code></td><td>Binary data</td><td><code>{&quot;blob_size&quot;: N}</code></td><td><code>attachment : BLOB</code></td></tr></tbody></table><h2 id="enum-type" tabindex="-1">Enum Type <a class="header-anchor" href="#enum-type" aria-label="Permalink to &quot;Enum Type&quot;">​</a></h2><p>A fixed set of allowed string values.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">priority : ENUM(low, medium, high, critical)</span></span></code></pre></div><p>The value must be one of the listed variants. Enums are stored as text internally.</p><h2 id="reference-type" tabindex="-1">Reference Type <a class="header-anchor" href="#reference-type" aria-label="Permalink to &quot;Reference Type&quot;">​</a></h2><p>A reference to an instance of another machine.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">assignee : REF(Agent)</span></span></code></pre></div><p>In JSON, refs are serialized as <code>{&quot;ref&quot;: &quot;Agent#01J5...&quot;}</code>.</p><h2 id="money-type" tabindex="-1">Money Type <a class="header-anchor" href="#money-type" aria-label="Permalink to &quot;Money Type&quot;">​</a></h2><p>A monetary amount with currency code.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">total : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MONEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(USD)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">price : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MONEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(EUR)</span></span></code></pre></div><p>In JSON, money values are <code>{&quot;amount&quot;: 9999, &quot;currency&quot;: &quot;USD&quot;}</code>. The amount is stored as an integer (cents).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Money values cannot be compared directly with INT. A guard like <code>total &gt; 0</code> will fail if <code>total</code> is <code>MONEY(USD)</code>. Compare money amounts explicitly.</p></div><h2 id="collection-types" tabindex="-1">Collection Types <a class="header-anchor" href="#collection-types" aria-label="Permalink to &quot;Collection Types&quot;">​</a></h2><h3 id="list" tabindex="-1">LIST <a class="header-anchor" href="#list" aria-label="Permalink to &quot;LIST&quot;">​</a></h3><p>An ordered collection of values.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tags : LIST(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>In JSON: <code>[&quot;tag1&quot;, &quot;tag2&quot;]</code>.</p><h3 id="set" tabindex="-1">SET <a class="header-anchor" href="#set" aria-label="Permalink to &quot;SET&quot;">​</a></h3><p>An unordered collection of unique values.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">categories : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>In JSON: <code>[&quot;a&quot;, &quot;b&quot;]</code> (deduplicated).</p><h3 id="map" tabindex="-1">MAP <a class="header-anchor" href="#map" aria-label="Permalink to &quot;MAP&quot;">​</a></h3><p>A key-value mapping.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">metadata : MAP(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>In JSON: <code>{&quot;key&quot;: &quot;value&quot;}</code>.</p><h2 id="type-constraints" tabindex="-1">Type Constraints <a class="header-anchor" href="#type-constraints" aria-label="Permalink to &quot;Type Constraints&quot;">​</a></h2><p>All types support <a href="./constraints.html">constraints</a> like <code>REQUIRED</code>, <code>OPTIONAL</code>, <code>DEFAULT</code>, <code>MIN</code>, <code>MAX</code>, <code>RANGE</code>, <code>UNIQUE</code>, and <code>PATTERN</code>.</p>`,32)])])}const k=t(i,[["render",o]]);export{u as __pageData,k as default};
